from pathlib import Path
import json
root=Path(__file__).resolve().parents[1]
notes=json.loads((root/'lessons/workshop-notes.json').read_text())
lessons=[
('Перша подорож','Скласти послідовність і передбачити момент зупинки.', [('Швидкість','80'),('Вперед','2 с'),('Стоп','')], 'S,80\nF,2000\nX,0\n', ['Поставте робот на підлогу перед вільною доріжкою. Телефон підключіть до мережі робота.','У «Мої блоки» додайте три блоки з таблиці. Перевіряльник читає їх уголос.','Натисніть «Зберегти в роботі», потім «Запустити». Спершу зробіть один короткий дослід.','Виміряйте шлях лінійкою. Повторіть тричі з одного місця. Змініть час на 1 с і порівняйте.'], 'Чи проїхав робот удвічі менше за 1 с? Чому розгін впливає на результат?', 'Робот рухається вперед близько 2 с і припиняє подавати PWM; колеса можуть трохи докотитися.', 'У PictoBlox: початок ESP32 → задати speed=80 → мій блок «Вперед» → чекати 2 с → мій блок «Стоп». Це замінює основну прошивку.'),
('Поворот ліворуч','Пояснити, чому різні швидкості боків змінюють напрям.', [('Швидкість','80'),('Ліворуч','0,7 с'),('Стоп','')], 'S,80\nL,700\nX,0\n', ['Підніміть колеса на підставці. Передбачте, який бік обертатиметься.','Зберіть програму. Лівий бік стоїть, правий рухається вперед. Це поворот по дузі.','Поставте робот на підлогу; позначте початковий напрям малярною стрічкою.','Змінюйте лише час на 0,1 с за спробу. Знайдіть час повороту приблизно на 90°. Запишіть його.'], 'Чи буде такий самий кут на килимі й гладкій підлозі?', 'Поворот ліворуч; немає вимоги точного 90° без попереднього підбору часу.', '«Ліворуч»: ліві PWM=0, праві вперед= speed. Повторний тест полярності обов’язковий.'),
('Малюємо квадрат','Побачити повторення в алгоритмі та похибку руху.', [('Швидкість','80'),('Вперед → Ліворуч','2 с → власний час; чотири рази'),('Стоп','')], 'S,80\nF,2000\nL,700\nF,2000\nL,700\nF,2000\nL,700\nF,2000\nL,700\nX,0\n', ['Перенесіть час повороту з попереднього заняття в усі чотири блоки. Значення 0,7 с лише початкове.','Складіть чотири однакові пари «Вперед», «Ліворуч». Порахуйте блоки до запуску.','Виконайте на великому вільному майданчику. Позначайте зупинки після сторін, не прикріплюйте маркер до неперевіреного шасі.','Виміряйте, наскільки кінцева точка відрізняється від початкової. Змінюйте один параметр за раз.'], 'Яка команда повторюється? Чому невелика похибка кута накопичується?', 'Чотири сторони й чотири повороти виконані в потрібному порядку; точність форми обговорюється, не оцінюється як помилка дитини.', 'У PictoBlox можна використати нативний блок «повторити 4». У нашому браузерному редакторі циклу немає: чотири пари додаються явно.'),
('Швидше й повільніше','Порівняти швидкість за однакового часу.', [('Швидкість','60'),('Вперед','2 с'),('Чекати','1 с'),('Швидкість','100'),('Вперед','2 с'),('Стоп','')], 'S,60\nF,2000\nW,1000\nS,100\nF,2000\nX,0\n', ['Підготуйте смугу завдовжки щонайменше 2 м без перешкод.','Порівняйте два відрізки, кожен по 2 с, зі швидкостями 60 і 100. Перед запуском зробіть прогноз.','Для точного порівняння розділіть програму на два окремі запуски з однієї мітки. Запишіть три результати для кожної швидкості.','Спробуйте швидкість 0. Усі колеса повинні стояти. Якщо 60 недостатньо для старту, учитель змінює початкове значення після перевірки струму.'], 'Чому число PWM не дорівнює швидкості в сантиметрах за секунду?', 'Результати записані; не вимагати лінійної залежності PWM і швидкості.', 'Нативний PWM є в PictoBlox; учительські «Мої блоки» обмежують speed до 0…180. Функція розгону основної прошивки автоматично не переноситься.'),
('П’ять очей робота','Прочитати покази й відкалібрувати відбиття.', [], None, ['Колеса нерухомі. Датчик на висоті 5±1 мм; поверхні підкладайте, не торкаючись електроніки.','Відкрийте «Очі робота». Запишіть 5 чисел на білому аркуші зліва направо.','Разом з учителем натисніть «Запам’ятати біле», зачекайте секунду. Усі п’ять сенсорів поставте над широким чорним; натисніть «Запам’ятати чорне», зачекайте секунду.','Перевірте напис «Калібрування готове». Пересувайте смугу під лівим, середнім і правим сенсорами. Запишіть, який показ зростає.'], 'Чи бачить датчик колір, чи кількість відбитого інфрачервоного світла?', 'Кожний чорний показ перевищує білий щонайменше на 300. За відсутності контрасту перевіряє вчитель: висоту, живлення, покриття, порядок проводів.', 'У PictoBlox нативно доступне аналогове читання. Використати GPIO32,33,34,35,36; не ADC2 під Wi-Fi. Нормалізація і збереження калібрування потребують підготовлених учителем блоків.'),
('Знаходимо чорну дорогу','Запустити пропорційне стеження і перевірити втрату лінії.', [('Швидкість','70'),('Сила Kp','25'),('За лінією','5 с'),('Стоп','')], 'S,70\nK,250\nA,5000\nX,0\n', ['Учитель готує чорну матову смугу 15–20 мм на білому: пряма і плавна дуга радіусом спочатку не менше 30 см. Це навчальний старт, не гарантована межа робота.','Повторіть біле/чорне калібрування. Середній сенсор поставте над смугою.','Збережіть блоки й запустіть. Якщо робот тікає від смуги, зупиніть: учитель перевіряє порядок каналів і напрям моторів.','На повільному русі перевірте розрив смуги. Робот має припинити PWM, а після 100 мс втрати перейти у зупинку. Перехрестя теж зупиняє його.'], 'Як робот вирішує, який бік прискорити, коли лінія праворуч?', 'Рух уздовж простої траси, керований поворот до лінії та зупинка при її втраті.', 'Повний P-контролер, Wi-Fi та калібрування реалізовані в C++. У PictoBlox їх треба скласти з власних блоків; нативного готового блока для цієї проводки не заявлено.'),
('Налаштовуємо силу повороту','Провести дослід, змінюючи лише Kp.', [('Швидкість','70'),('Сила Kp','15, потім 25, потім 35'),('За лінією','5 с'),('Стоп','')], 'S,70\nK,150\nA,5000\nX,0\n', ['Використайте ту саму трасу, батареї й швидкість 70. Почніть з Kp=15.','Повторіть із Kp=25 і 35. Після зміни блока знову зберігайте програму.','Для кожної спроби записуйте: чи пройшов дугу, чи хитається, чи втратив смугу.','Виберіть найменше Kp, за якого робот упевнено проходить вашу трасу. Значення залежать від моторів, покриття й заряду.'], 'Чому дуже велике Kp може спричинити хитання замість кращого руху?', 'Учень порівнює щонайменше три спроби й пояснює вибір; немає одного правильного Kp для всіх роботів.', 'Помилка −2…+2; поправка=Kp×помилка. Формули: ліворуч=speed+поправка, праворуч=speed−поправка, межі 0…180. Це P, без I та D.'),
('Телефон і самостійна подорож','Розрізнити ручне керування та автономну програму.', [('Швидкість','80'),('Вперед','1 с'),('Праворуч','0,5 с'),('Стоп','')], 'S,80\nF,1000\nR,500\nX,0\n', ['Знайдіть Wi-Fi «Mandrivnyk-…», пароль від учителя; відкрийте http://192.168.4.1. Інтернет не потрібний.','Тримайте «Вперед», відпустіть. Повторіть «Назад», «Ліворуч», «Праворуч». Перед перемиканням дочекайтеся зупинки.','Разом з учителем перевірте втрату зв’язку при піднятих колесах: PWM має зникнути не пізніше 370 мс після останньої прийнятої команди. Дитина оцінює лише факт, час вимірює дорослий.','Збережіть коротку програму, вимкніть телефонний Wi-Fi. На роботі зі стану спокою тримайте фізичну кнопку понад 1 с і відпустіть: програма виконається автономно. Натискання під час руху зупиняє.'], 'Де зберігається програма? Чим її запуск відрізняється від утримання кнопки на телефоні?', 'Ручний режим зупиняється при втраті команд; збережена програма працює без телефона й завершується. Після увімкнення живлення немає самостарту.', 'WebServer і власний редактор входять до C++ прошивки. Нативну сумісність цього інтерфейсу з PictoBlox/mBlock не заявлено.')]
(root/'lessons/programs').mkdir(exist_ok=True)
for n,(title,goal,blocks,program,steps,question,check,mapping) in enumerate(lessons,1):
    s=f'# Заняття {n:02d}. {title}\n\n**Вік:** 8–10 років. **Час:** 35–45 хв. **Мета:** {goal}\n\n'
    s=s.replace('\n\n', '\n\n'+notes[str(n)]+'\n\n', 1)
    s+='Потрібно: прийнятий учителем робот, заряджені NiMH, телефон/планшет, білий папір, чорна матова стрічка, лінійка й аркуш спостережень. Урок проходить у власному браузерному редакторі робота. Для PictoBlox нижче наведено окреме перенесення, а не готовий імпорт.\n\n'
    s+='## Перед початком\n\nУчитель перевіряє допуск першого зразка, вільну підлогу та доступ до S1. Діти не паяють, не торкаються коліс у русі й не переставляють роз’єми під живленням. Один учень складає блоки, другий звіряє порядок; через 10 хв міняються ролями. Перший дослід нового руху — з піднятими колесами.\n\n'
    s+='## Хід заняття\n\n5 хв — прогноз; 20–25 хв — досліди; 5 хв — обговорення; 5 хв — вимкнення та прибирання.\n\n'
    s+='\n'.join(f'{i}. {x}' for i,x in enumerate(steps,1))+'\n\n'
    if blocks:
        s+='## Моя програма\n\n| Блок | Значення |\n|---|---|\n'+'\n'.join(f'| {a} | {b} |' for a,b in blocks)+'\n\n'
        s+=f'Для вчителя: [текст протоколу](programs/lesson-{n:02d}.txt). У браузері скласти ті самі блоки вручну. Текст передається через POST `/program`; це не файл Scratch.\n\n'
        (root/f'lessons/programs/lesson-{n:02d}.txt').write_text(program)
    else:
        s+='Рухова програма цього заняття не потрібна. Досліджуємо числа з нерухомих датчиків.\n\n'
    s+=f'## Перевіряємо\n\n{check}\n\n**Питання:** {question}\n\n| Спроба | Що змінили | Що побачили |\n|---|---|---|\n| 1 | | |\n| 2 | | |\n| 3 | | |\n\n'
    s+=f'## Нотатка вчителю про блоки\n\n{mapping}\n\n[Порівняння середовищ і рецепти функцій](../docs/programming.md). Якщо завантажували PictoBlox, для наступних браузерних уроків поверніть C++ прошивку й перевірте калібрування.\n\nНаприкінці: СТОП → S1 вимкнено → робот на полицю. AA заряджає дорослий у зовнішньому NiMH зарядному пристрої; у роботі заряджання немає.\n'
    (root/f'lessons/lesson-{n:02d}.md').write_text(s)
print('Created 8 lessons and 7 runnable text programs')
